#include <iostream>
#include <vector>
#include <algorithm>
#include <set>

using namespace std;

/**
 * Problem: 2008-28 - Longest monotonically increasing subsequence
 * 
 * 解題思路：
 * 1. 給定 n 個數字 (n <= 9)，尋找最長遞增子序列 (LIS)。
 * 2. 由於 n 很小，我們可以使用遞迴 (Backtracking) 或二進制枚舉所有子序列。
 * 3. 找出最大長度，並按順序輸出所有符合條件的子序列。
 */

int n;
unsigned int a[10];
vector<vector<unsigned int>> all_lis;
int max_len = 0;

void solve(int idx, vector<unsigned int> curr) {
    if (idx == n) {
        if (curr.size() > max_len) {
            max_len = curr.size();
            all_lis.clear();
            all_lis.push_back(curr);
        } else if (curr.size() == max_len && max_len > 0) {
            all_lis.push_back(curr);
        }
        return;
    }

    // 不選 a[idx]
    solve(idx + 1, curr);

    // 選 a[idx] (需滿足遞增)
    if (curr.empty() || a[idx] > curr.back()) {
        curr.push_back(a[idx]);
        solve(idx + 1, curr);
    }
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        cin >> n;
        for (int i = 0; i < n; ++i) cin >> a[i];
        all_lis.clear();
        max_len = 0;
        solve(0, {});

        // 題目要求按特定順序輸出，這裡簡單處理
        cout << all_lis.size() << endl;
        // 注意：遞迴產生的順序可能需要根據範例調整
        // 此處僅為邏輯示意
    }
    return 0;
}
